	private Color getPhantomEdgeColor(E edge, bool isLeft) {
		if (isLeft) {
			if (isTrueEdge(edge)) {
				return new GColor("color.palette.darkkhaki");
			}

			return Palette.GREEN;
		}
		if (isTrueEdge(edge)) {
			return new GColor("color.palette.navy");
		}
		return new GColor("color.palette.dodgerblue");
	}

	private bool isTrueEdge(E edge) {
		return true;
	}
}
